<template><div class="ops-page"><HeaderBar /><main class="ops-main"><div class="ops-toolbar"><div><span class="ops-eyebrow">OFFICIAL RESOURCES</span><h1>官方资源</h1><p class="ops-lead">维护平台发布的公共模板。编辑草稿、独立审批、发布版本，用户的私有资源不在此列表。</p></div><el-button v-if="can('official.resource.write')" type="primary" @click="edit()">新建模板草稿</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><section class="ops-panel"><div class="ops-toolbar"><h2>角色模板</h2><el-button size="small" :loading="loading" @click="load">刷新</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无官方模板"><el-table-column prop="templateName" label="模板名称" min-width="170" /><el-table-column prop="agentName" label="角色" min-width="150" /><el-table-column prop="version" label="版本" width="90" /><el-table-column prop="reviewStatus" label="发布状态" min-width="130" /><el-table-column label="操作" min-width="280"><template slot-scope="s"><el-button v-if="can('official.resource.write') && s.row.reviewStatus === 'DRAFT'" type="text" @click="edit(s.row)">编辑草稿</el-button><el-button v-if="can('official.resource.write')" type="text" :disabled="busy" @click="clone(s.row)">复制为新版本</el-button><el-button v-if="can('official.resource.publish') && s.row.reviewStatus === 'DRAFT' && !approvalFor(s.row)" type="text" :disabled="busy" @click="requestApproval(s.row)">申请发布</el-button><el-button v-if="approvalFor(s.row) && approvalFor(s.row).status === 'APPROVED' && can('official.resource.publish')" type="text" :disabled="busy" @click="publish(s.row)">发布批准版本</el-button><el-tag v-else-if="approvalFor(s.row)" size="mini" type="warning">等待审批</el-tag></template></el-table-column></el-table></section><OpsOfficialKnowledge /><section class="ops-note"><i class="el-icon-lock" /><p>发布审批仅处理公开草稿。运营账号不能读取用户聊天、记忆或私有知识库，也不能直接覆盖已发布版本。</p></section><el-dialog :title="form.id ? '编辑官方模板草稿' : '新建官方模板草稿'" :visible.sync="dialog" width="min(750px,94vw)" :close-on-click-modal="false"><el-form label-width="105px"><el-form-item label="模板名称"><el-input v-model="form.templateName" maxlength="100" /></el-form-item><el-form-item label="角色名称"><el-input v-model="form.agentName" maxlength="64" /></el-form-item><el-form-item label="角色提示词"><el-input v-model="form.systemPrompt" type="textarea" :rows="9" /></el-form-item><el-collapse><el-collapse-item title="模型与语音配置" name="models"><p class="ops-muted">填写已批准服务目录中的模型 ID；留空字段由服务端按模板规则校验。</p><el-form-item v-for="field in modelFields" :key="field.key" :label="field.label"><el-input v-model="form[field.key]" /></el-form-item></el-collapse-item></el-collapse></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button :disabled="busy" @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></span></el-dialog></main></div></template>
<script>
import OpsOfficialKnowledge from './OpsOfficialKnowledge.vue';
import HeaderBar from '@/components/HeaderBar.vue';
import { platformRequest } from '@/apis/platform';
import { hasPermission } from '@/security/session';
const modelFields = [{key:'llmModelId',label:'对话模型'},{key:'asrModelId',label:'语音识别'},{key:'ttsModelId',label:'语音合成'},{key:'ttsVoiceId',label:'音色 ID'},{key:'vadModelId',label:'语音活动检测'},{key:'slmModelId',label:'辅助模型'},{key:'vllmModelId',label:'视觉模型'},{key:'memModelId',label:'记忆模型'},{key:'intentModelId',label:'意图模型'},{key:'language',label:'语言'},{key:'langCode',label:'语言代码'}];
export default {
  components: { HeaderBar, OpsOfficialKnowledge }, data() { return { rows: [], approvals: [], loading: false, busy: false, error: '', dialog: false, form: {}, saveError: '', modelFields }; }, created() { this.load(); },
  methods: {
    can(permission) { return hasPermission(this.$store.state.userInfo,permission); },
    async load() { this.loading = true; this.error = ''; try { const [rows, approvals] = await Promise.all([platformRequest('GET','/ops/content/templates'),this.can('official.resource.publish') ? platformRequest('GET','/ops/approvals') : []]); this.rows = Array.isArray(rows) ? rows : rows.list || []; this.approvals = Array.isArray(approvals) ? approvals : approvals.list || []; } catch (error) { this.error = error.message; } finally { this.loading = false; } },
    approvalFor(row) { return this.approvals.find(item => item.action === 'official.resource.publish' && String(item.targetId) === String(row.id) && String(item.version) === String(row.version) && item.requesterId === this.$store.state.userInfo.employeeId && ['PENDING','APPROVED'].includes(item.status) && new Date(item.expiresAt).getTime() > Date.now()); },
    edit(row = {}) { this.form = { ...Object.fromEntries(modelFields.map(field=>[field.key,''])), templateName:'',agentName:'',systemPrompt:'',sort:0,...row }; this.saveError = ''; this.dialog = true; },
    async save() { if (this.busy) return; if (!this.form.templateName.trim() || !this.form.agentName.trim()) { this.saveError = '请填写模板与角色名称'; return; } this.busy = true; this.saveError = ''; try { const payload = { templateName: this.form.templateName, agentName: this.form.agentName, systemPrompt:this.form.systemPrompt,sort:this.form.sort,...Object.fromEntries(modelFields.map(field=>[field.key,this.form[field.key] || null])) }; await platformRequest(this.form.id?'PUT':'POST',this.form.id?`/ops/content/templates/${encodeURIComponent(this.form.id)}`:'/ops/content/templates',payload); this.dialog=false; await this.load(); } catch (error) { this.saveError=error.message; } finally { this.busy=false; } },
    async clone(row) { this.busy=true; try { await platformRequest('POST',`/ops/content/templates/${encodeURIComponent(row.id)}/clone`); await this.load(); } catch (error) { this.$message.error(error.message); } finally { this.busy=false; } },
    async requestApproval(row) { this.busy=true; try { const request = await platformRequest('GET',`/ops/content/templates/${encodeURIComponent(row.id)}/prepare`); await platformRequest('POST','/ops/approvals',request); this.$message.success('发布申请已提交，等待独立审批'); await this.load(); } catch (error) { this.$message.error(error.message); } finally { this.busy=false; } },
    async publish(row) { const approval=this.approvalFor(row); if (!approval || approval.status !== 'APPROVED' || this.busy) return; this.busy=true; try { await platformRequest('POST',`/ops/content/templates/${encodeURIComponent(row.id)}/publish`,{}, {headers:{'X-Ops-Approval-Id':approval.id}}); this.$message.success('批准版本已发布'); await this.load(); } catch (error) { this.$message.error(error.message); } finally { this.busy=false; } },
  },
};
</script>
